def price_page(lethal=False):
    blocks = [h("Уровень 3: Нити Ильбеша"),
        p("**Натяжение** — один общий счётчик. Оно начинается с 0. При повышении на любое число уровней бросьте **1к4 один раз** и получите указанное осложнение. Повторный результат не добавляет вторую копию эффекта. Все действующие осложнения используют столбец текущего Натяжения и усиливаются вместе."),
        p("**БМ — бонус мастерства.** Осложнения действуют на все ваши заклинания, включая знакомые. Эффект, полученный после разрешения заклинания, не применяется к нему задним числом."),
        table(["к4", "Осложнение", "Натяжение 1", "Натяжение 2", "Натяжение 3"], PRICE_ROWS, [22, 216, 79, 79, 79]),
    ]
    if lethal:
        blocks += [p("**Гнев Ильбеша: Натяжение 4 или выше.** Разрешите заклинание или умение, вызвавшее повышение, затем немедленно наступает Гнев: вы погибаете, тело уничтожается. Спасброски от смерти не совершаются. Остальные существа в радиусе **20 футов** совершают спасбросок Ловкости против Сл ваших заклинаний и получают **(3 × БМ)к4** урона, половину при успехе. Последний результат к4 определяет тип: 1 — огонь; 2–3 — силовое поле; 4 — излучение."),
            p("До разрешения Гнева осложнения используют столбец 3. Гнев наступает и после прерванной попытки накладывания, если её цена подняла Натяжение до 4. Эффекты, предотвращающие смерть, работают по своим правилам; если вы выжили, до продолжительного отдыха вы не можете накладывать заклинания 1-го круга или выше и использовать умения этого подкласса. На 14-м уровне «Обман Ильбеша» может заменить весь этот исход."),
            p("**Восстановление.** Продолжительный отдых снижает Натяжение до 0, снимает все осложнения и запрет на колдовство. Заговоры сами по себе не повышают Натяжение.")]
    else:
        blocks += [p("**Предел.** Натяжение не может превышать 3. Вы не можете добровольно использовать умение, цена которого подняла бы его выше 3; ресурсы на такую попытку не тратятся. Эта версия не содержит автоматической смерти от счётчика, но урон и потеря концентрации остаются опасны."),
            p("**Восстановление.** После продолжительного отдыха Натяжение становится 0, все осложнения прекращаются. Снятие одного осложнения другими умениями само по себе не восстанавливает запас приёмов.")]
    return blocks

